def make():
 value=1
 class Holder:
  read=lambda self:value
 def set_value(new):
  nonlocal value
  value=new
 def delete_value():
  nonlocal value
  del value
 return Holder(),set_value,delete_value
h,set_value,delete_value=make()
print(h.read())
set_value(7)
print(h.read())
delete_value()
try:h.read()
except NameError:print('deleted')

